import asyncio

paths = ["34aaa432","41229f1b","44d1a529","5b2f8b98","71403a74","855581af","94d0a5a9","ae18c2af","b1aa6f4e","c35375a9","eb12994f","f0eaea04"]
reqs = [("nodes/"+p+".txt") for p in paths]
res = await asyncio.gather(*[yuki_workspace_read({"path": r}) for r in reqs])
